from typing import Annotated
from fastapi import Depends, FastAPI

app = FastAPI()
calls = {"get_db": 0}

def get_db():
    calls["get_db"] += 1
    yield {"session": calls["get_db"]}

def users_repo(db: Annotated[dict, Depends(get_db)]):
