oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")
app = FastAPI()
USERS = {"alice": {"username": "alice"}}

class User(BaseModel):
    username: str

def get_current_user(token: Annotated[str, Depends(oauth2_scheme)]) -> User:
    unauthorized = HTTPException(
        401, "Could not validate credentials", headers={"WWW-Authenticate": "Bearer"}
    )
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=["HS256"])
    except InvalidTokenError:
        raise unauthorized
    user = USERS.get(payload.get("sub"))
    if user is None:
        raise unauthorized
    return User(**user)

@app.get("/users/me")
def read_me(user: Annotated[User, Depends(get_current_user)]):
    return user
```

`InvalidTokenError` covers bad signatures, malformed tokens and expired ones (`ExpiredSignatureError` is a subclass).

List the scopes on `OAuth2PasswordBearer`, require them with `Security(..., scopes=[...])`, and enforce them in the dependency via `SecurityScopes`.

```python
from typing import Annotated
from fastapi import FastAPI, HTTPException, Security
from fastapi.security import OAuth2PasswordBearer, SecurityScopes

oauth2_scheme = OAuth2PasswordBearer(
    tokenUrl="token",
    scopes={"items:read": "Read items", "items:write": "Modify items"},
)
app = FastAPI()
TOKENS = {"tok-reader": {"sub": "alice", "scopes": ["items:read"]}}  # stand-in for decoded JWTs

def get_claims(scopes: SecurityScopes, token: Annotated[str, Security(oauth2_scheme)]) -> dict:
    claims = TOKENS.get(token)
    if claims is None:
        raise HTTPException(401, "Invalid token", headers={"WWW-Authenticate": "Bearer"})
    if not set(scopes.scopes) <= set(claims["scopes"]):
        raise HTTPException(403, "Not enough permissions")
    return claims

@app.get("/items")
def read_items(claims: Annotated[dict, Security(get_claims, scopes=["items:read"])]):
    return {"owner": claims["sub"]}

@app.post("/items")
def create_item(claims: Annotated[dict, Security(get_claims, scopes=["items:write"])]):
    return {"created_by": claims["sub"]}
```

