Subclass `BaseHTTPMiddleware`, accept options in `__init__`, and put the logic in `dispatch`.

```python
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from starlette.middleware.base import BaseHTTPMiddleware

class BlockUserAgents(BaseHTTPMiddleware):
    def __init__(self, app, blocked: list[str]):
        super().__init__(app)
        self.blocked = [b.lower() for b in blocked]

    async def dispatch(self, request: Request, call_next):
        agent = request.headers.get("user-agent", "").lower()
        if any(b in agent for b in self.blocked):
            return JSONResponse({"detail": "Forbidden"}, status_code=403)
        return await call_next(request)

app = FastAPI()
app.add_middleware(BlockUserAgents, blocked=["badbot", "scrapy"])

@app.get("/")
def index():
    return {"ok": True}
```

`add_middleware` passes its keyword arguments to `__init__`. Override `dispatch`, not `__call__`.

