@app.post("/transfers")
def transfer(data: TransferIn, session: SessionDep):
    with session.begin():
        src = session.get(Account, data.from_id, with_for_update=True)
        dst = session.get(Account, data.to_id, with_for_update=True)
        if src is None or dst is None:
            raise HTTPException(status_code=404, detail="Account not found")
        if src.balance < data.amount:
            raise HTTPException(status_code=400, detail="Insufficient funds")
        src.balance -= data.amount
        dst.balance += data.amount
    return {"from_balance": src.balance, "to_balance": dst.balance}
```

`with_for_update=True` locks both rows on databases that support `SELECT ... FOR UPDATE` (e.g. PostgreSQL), preventing concurrent transfers from reading stale balances.

