from typing import Annotated

from fastapi import Cookie, FastAPI
from fastapi.testclient import TestClient

app = FastAPI()


@app.get("/prefs")
async def prefs(theme: Annotated[str, Cookie()] = "light"):
    return {"theme": theme}


def test_theme_from_cookie():
    client = TestClient(app, cookies={"theme": "dark"})
    assert client.get("/prefs").json() == {"theme": "dark"}

    client.cookies.set("theme", "solarized")
    assert client.get("/prefs").json() == {"theme": "solarized"}


def test_default_theme():
    client = TestClient(app)
    assert client.get("/prefs").json() == {"theme": "light"}
```

Passing `cookies=` to a single call such as `client.get("/prefs", cookies={...})` still works but emits an httpx `DeprecationWarning`, because cookie persistence per request is ambiguous. Cookies set by responses (`Set-Cookie`) are stored on the client automatically, which is handy for login flows.

Create a fresh `TestClient` per test, or call `client.cookies.clear()`, so cookies from one test don't leak into the next.

